const visualLine = clean(visual, 100) !== '' ? `视频画面：${clean(visual, 100)}。` : '';
const saidLine = clean(shareLine, 60) !== '' ? `你自己本来想说的是：「${clean(shareLine, 60)}」。` : '';
const reason = `你在${platform}上刷到一个视频《${clean(title, 60) || '没写标题'}》${author ? `（${clean(author, 20)}）` : ''}，链接 ${url} 。` +
